<script setup>
import { onMounted,ref } from 'vue';
import ThemeSelect from '../common/ThemeSelect.vue';
import { api } from '../../lib/api.js';
const sources=ref([]),selectedSource=ref(''),config=ref(null),selected=ref([]),error=ref(''),notice=ref(''),busy=ref(false);
const labels={added:'신규',removed:'삭제됨',changed:'이름 변경'};
async function load(){error.value='';selected.value=[];config.value=null;if(!selectedSource.value)return;try{config.value=await api(`admin/proxy-sources/${selectedSource.value}/sync`);}catch(e){error.value=e.message;}}
onMounted(async()=>{try{sources.value=await api('admin/proxy-sources');selectedSource.value=sources.value[0]?.id||'';await load();}catch(e){error.value=e.message;}});
async function act(kind,action){busy.value=true;error.value='';notice.value='';try{const prefix=`admin/proxy-sources/${selectedSource.value}/sync`;if(kind==='save'){const {enabled,interval,scheme,public_port}=config.value;config.value=await api(prefix,{method:'PUT',body:JSON.stringify({enabled,interval:Number(interval),scheme,public_port:public_port?Number(public_port):null})});notice.value='변경 감지 설정을 저장했어요.';}else if(kind==='check'){config.value=await api(prefix+'/check',{method:'POST'});}else{config.value=await api(prefix+'/review',{method:'POST',body:JSON.stringify({revision:config.value.revision,change_ids:selected.value,action})});selected.value=[];notice.value=action==='apply'?'선택한 변경을 공개 링크에 반영했어요.':'선택한 변경을 반영하지 않고 확인 처리했어요.';}}catch(e){error.value=e.message;}finally{busy.value=false;}}
</script>
<template><section class="settings-section"><p class="settings-description">등록한 리버스 프록시 API의 신규·삭제·이름 변경을 주기적으로 감지합니다. 관리자 승인 전에는 공개 링크를 추가하거나 숨기지 않습니다. URL이 바뀌면 기존 URL 삭제와 새 URL 추가로 표시합니다.</p><p v-if="error" class="form-error" role="alert">{{ error }}</p><p v-if="notice" class="form-notice" role="status">{{ notice }}</p><div class="settings-card"><div class="settings-form"><label>서비스<ThemeSelect v-model="selectedSource" label="변경 감지 서비스" :disabled="busy" placeholder="API 연결을 먼저 등록해 주세요" @change="load" :options="sources.map(item=>({value:item.id,label:item.name}))" /></label></div><p v-if="!sources.length" class="settings-empty">API 링크 가져오기에서 서비스를 먼저 연결해 주세요.</p><form v-if="config" class="settings-form" @submit.prevent="act('save')"><label class="checkbox-label"><input v-model="config.enabled" type="checkbox" />주기적 변경 감지 사용</label><label>확인 간격 (초)<input v-model="config.interval" type="number" min="300" max="86400" required /></label><label>호스트 프로토콜<ThemeSelect v-model="config.scheme" label="변경 감지 프로토콜" :options="[{value:'auto',label:'자동 · 호스트 설정 사용'},{value:'https',label:'HTTPS'},{value:'http',label:'HTTP'}]" /></label><label>외부 포트 (선택)<input v-model="config.public_port" type="number" min="1" max="65535" /></label><div class="inline-actions"><button class="primary-button" :disabled="busy">변경 감지 설정 저장</button><button class="secondary-button" type="button" :disabled="busy||!config.revision" @click="act('check')">지금 변경 확인</button></div><small v-if="config.checked_at">최근 확인: {{ new Date(config.checked_at*1000).toLocaleString('ko-KR') }}</small><p v-if="config.error" class="form-error" role="alert">{{ config.error }}</p></form></div>
<div v-if="config?.checked_at&&!config.error" class="settings-card"><div class="card-heading"><h2>승인 대기 변경 {{ config.changes.length }}개</h2><button v-if="config.changes.length" class="secondary-button" :disabled="busy" @click="selected=selected.length===config.changes.length?[]:config.changes.map(item=>item.id)">{{ selected.length===config.changes.length?'선택 해제':'전체 선택' }}</button><button class="secondary-button" :disabled="busy" @click="load">새로고침</button></div><div class="import-entry-list"><label v-for="item in config.changes" :key="item.id" class="import-entry"><input v-model="selected" type="checkbox" :value="item.id" :disabled="busy" /><span><strong>{{ labels[item.kind] }} · {{ item.name }}</strong><small>{{ item.url }}</small><small v-if="item.kind==='changed'">기존 이름: {{ item.previous_name }}</small></span></label></div><p v-if="!config.changes.length" class="settings-empty">새로운 변경이 없습니다.</p><div class="inline-actions"><button class="primary-button" :disabled="busy||!selected.length" @click="act('review','apply')">선택한 변경 승인</button><button class="secondary-button" :disabled="busy||!selected.length" @click="act('review','ignore')">반영 없이 확인 처리</button></div></div></section></template>
